export function row(page: Page, personId: string): Locator {
  return page.getByTestId(`person-row-${personId}`);
}

function rows(page: Page): Locator {
  return page.locator('[data-testid^="person-row-"]');
}

function rowsNamed(page: Page, name: string): Locator {
  const re = new RegExp(`^\\s*${escapeRe(name.trim())}(\\s\\([^()]*\\))?\\s*$`, 'i');
  return rows(page).filter({ has: page.getByTestId('person-name').filter({ hasText: re }) });
}

/** The id of the (newest) person row showing this name. */
export async function personId(page: Page, name: string): Promise<string> {
  const r = rowsNamed(page, name).last();
  await expect(r).toBeVisible({ timeout: WAIT });
  return idOf(await r.getAttribute('data-testid'), 'person-row-');
}

type PersonFields = { name?: string; grade?: string; gradeFrom?: string; terms?: string; termsFrom?: string; contact?: string; tags?: string };

/** Fill the person form. `clear` (an add) also empties every optional field the test does not
 *  give, so nothing typed for a refused add carries into this one; an edit leaves the
 *  fields it is not given as the editor filled them. */
async function fillPersonForm(page: Page, f: PersonFields, clear = false) {
  if (f.name !== undefined) await page.getByTestId('person-form-name').fill(f.name);
  if (f.grade !== undefined) await page.getByTestId('person-form-grade').selectOption(f.grade);
  for (const [key, testid] of [['gradeFrom', 'person-form-grade-from'], ['terms', 'person-form-terms'],
    ['termsFrom', 'person-form-terms-from'], ['contact', 'person-form-contact'], ['tags', 'person-form-tags']] as const) {
    const v = f[key];
    if (v !== undefined) await page.getByTestId(testid).fill(v);
    else if (clear) await setField(page, testid, undefined);
  }
}

/** Add a person through the form. The new row's id, or null when the form refused. */
export async function addPerson(page: Page, f: PersonFields & { name: string; grade: string }): Promise<string | null> {
  const before = await ids(rows(page), 'person-row-');
  await fillPersonForm(page, f, true);
  await page.getByTestId('person-form-submit').click();
  let added: string | null = null;
  const ok = await until(page, async () => (added = await addedPerson(page, before, f.name)) !== null,
    page.getByTestId('person-form-error'), 'add person');
  return ok ? added : null;
}

export async function editOpen(page: Page, personId: string): Promise<void> {
  await page.getByTestId(`person-edit-${personId}`).click();
  await expect(page.getByTestId('person-form-name')).not.toHaveValue('', { timeout: WAIT });
  editing.set(page, personId);
}

/**
 * Save the open editor with these changes; true when saved, false when the form refused. `shows` is
 * the grade the row shows once saved: by default the grade entered, but a grade dated from another
 * day may leave the grade in force on the sheet's today unchanged.
 */
type Shows = string | { grade?: string; terms?: string };

export async function editSave(page: Page, f: PersonFields, shows?: Shows): Promise<boolean> {
  const id = editing.get(page);
  if (!id) throw new Error('editSave without editOpen');
  const want = typeof shows === 'string' ? { grade: shows } : (shows ?? {});
  const grade = want.grade ?? f.grade;                       // the grade the row shows once saved
  const terms = want.terms ?? f.terms;                       // the terms in force the row shows
  const r = row(page, id);
  const shows_ = async () => {
    if (f.name !== undefined && plainName(await shown(r.getByTestId('person-name'))) !== f.name.trim()) return false;
    if (grade !== undefined && await shown(r.getByTestId('person-grade')) !== grade) return false;

package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Applies the edit: the name, and the form's grade from its from-date (the sheet's today when blank),
 * keeping the grades already recorded. A grade left as the row showed it (the one in force on the
 * sheet's today) with the from-date blank records nothing. Their own terms become the form's, and
 * whether they differ from those the row showed is published for the audit; likewise their contact. Their tags become the form's.
 */
public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, @Val Sheet sheet, Out<TermsEdit> termsEdit,
            Out<ContactEdit> contactEdit) {
        person.setName(request.name());
        Integer terms = request.termsDays();
        termsEdit.set(new TermsEdit(!java.util.Objects.equals(terms, person.getTerms())));
        person.setTerms(terms);
        String contact = request.contactValue();
        contactEdit.set(new ContactEdit(!java.util.Objects.equals(contact, person.getContact())));
        person.setContact(contact);
        person.setTags(request.tagsValue());
        boolean dated = !request.gradeFrom().isEmpty();
        if (!dated && request.grade().equals(person.gradeOn(sheet.today()))) return;
        person.setGradeFrom(request.grade(), dated ? LocalDate.parse(request.gradeFrom()) : sheet.today());
    }
}
package net.officefloor.hq.app.person;

/**
 * A person as the screen sends it, to add or to edit: a name, a grade (A, B or C) and the date the
 * grade is from (yyyy-MM-dd; blank for the sheet's today). An edit also names the version of the
 * person it was made from. A contact is any text (blank: none). Tags are comma separated (blank: none). Their own terms are a whole number of days, 0 or more (blank: none).
 */
public record PersonRequest(String name, String grade, Long version, String gradeFrom, String terms, String contact, String tags) {
    /** The terms as a number of days; null when blank. */
    public Integer termsDays() { return terms == null || terms.isEmpty() ? null : Integer.valueOf(terms); }

    /** The contact as stored: trimmed and lower-cased; null when blank (none). */
    public String contactValue() {
        String c = contact == null ? "" : contact.trim().toLowerCase(java.util.Locale.ROOT);
        return c.isEmpty() ? null : c;
    }

    /** The tags as stored: each trimmed and lower-cased, repeats dropped, sorted and comma separated; null when none. */
    public String tagsValue() {
        java.util.TreeSet<String> set = new java.util.TreeSet<>();
        if (tags != null) {
            for (String tag : tags.split(",")) {
                String t = tag.trim().toLowerCase(java.util.Locale.ROOT);
                if (!t.isEmpty()) set.add(t);
            }
        }
        return set.isEmpty() ? null : String.join(",", set);
    }

    /** A person's name as the form takes it: trimmed, required, at most 200 characters. */
    public static String checkName(String raw) throws InvalidPersonException {
        String name = raw == null ? "" : raw.trim();
        if (name.isEmpty()) throw new InvalidPersonException("A name is required");
        if (name.length() > 200) throw new InvalidPersonException("A name is at most 200 characters");
        return name;
    }

    /** The request as the person form takes it, checked by the form's rules: trimmed, terms, contact and tags normalised. */
    public static PersonRequest checked(PersonRequest request) throws InvalidPersonException {
        if (request == null) throw new InvalidPersonException("A name is required");
        String name = PersonRequest.checkName(request.name());
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!java.util.Set.of("A", "B", "C").contains(grade)) throw new InvalidPersonException("A grade is one of A, B or C");
        String gradeFrom = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!gradeFrom.isEmpty()) {
            try {
                java.time.LocalDate.parse(gradeFrom);
            } catch (java.time.format.DateTimeParseException e) {
                throw new InvalidPersonException("A from-date is a date, yyyy-MM-dd");
            }
        }
        String terms = request.terms() == null ? "" : request.terms().trim();
        if (!terms.isEmpty() && !terms.matches("\\d{1,6}")) {
            throw new InvalidPersonException("Terms are a whole number of days, 0 or more, or blank");
        }
        if (!terms.isEmpty()) terms = String.valueOf(Integer.parseInt(terms));
        String contact = request.contact() == null ? "" : request.contact().trim().toLowerCase(java.util.Locale.ROOT);
        if (contact.length() > 200) throw new InvalidPersonException("A contact is at most 200 characters");
        String tags = request.tags() == null ? "" : request.tags();
        PersonRequest checked = new PersonRequest(name, grade, request.version(), gradeFrom, terms, contact, tags);
        String stored = checked.tagsValue();
        if (stored != null && stored.length() > 2000) throw new InvalidPersonException("Tags are at most 2000 characters");
        return checked;
    }
}
