    private void saveGrades(Person person) {
        jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ?",
                person.getSheetId(), person.getId());
        person.getDatedGrades().forEach((from, grade) -> jdbc.update(
